/* 参考代码（CubeIDE / HAL，USART1 115200）：
   CubeMX 中使能 USART1 Asynchronous 后，在 main.c 或单独 debug.c 中加入： */

#include <stdio.h>
#include "usart.h"

/* 写法二：GCC / newlib-nano（CubeIDE 推荐） */
int _write(int fd, char *ptr, int len) {
    HAL_UART_Transmit(&huart1, (uint8_t *)ptr, len, 0xFFFF);
    return len;
}

